namespace CastroFallas.MiniQuote.Api.Services.Auth;

/// <summary>
/// Small corporate images kept inline in multipart mail, not fetched from the website.
/// Base64 is fixed public artwork, never private OTP content.
/// </summary>
public static class OtpEmailAssets
{
    public const string LogoCid = "cf-otp-logo";
    public const string GlobeCid = "cf-otp-globe";
    private const string LogoBase64 = "";
    // Generated from frontend/public/images/tracking-red.webp with an exclusively horizontal white fade (left to right); JPEG for mail client compatibility.
    private const string GlobeBase64 = "";

    public static IReadOnlyList<InlineEmailImage> Images { get; } =
    [
        new("castro-fallas-g.png", "image/png", LogoCid, Convert.FromBase64String(LogoBase64)),
        new("castro-fallas-globo.jpg", "image/jpeg", GlobeCid, Convert.FromBase64String(GlobeBase64))
    ];
}
